'use strict';
let menuOpen=false,menuOwnsPause=false,menuReplaySpeed=0;
const menuItems=['menuResume','menuMatch','menuVideo','menuReplays','menuChat','menuHelp','menuHome'];
function refreshMenu(){const g=(replay||room).gameState;$('menuScore').textContent=(g?.redScore||0)+' : '+(g?.blueScore||0);$('menuClock').textContent=fmt(g?.timeElapsed);$('menuStadium').textContent=(replay?.state?.stadium||stadium).name;$('menuPlayers').textContent=(replay?.state||room.state).players.length;$('menuPing').textContent=Math.round(net.rtt);$('cameraMode').value=settings.camera||'stadium';$('matchZoom').value=settings.zoom;$('matchZoomValue').textContent=settings.zoom.toFixed(2)+'×';$('matchSound').checked=settings.sound;}
function menuPane(id,button){for(const pane of ['menuOverview','menuMatchPane','menuVideoPane','menuReplayPane','menuChatPane'])$(pane).hidden=pane!==id;for(const b of menuItems)$(b).classList.toggle('selected',b===button);}
function openMatchMenu(pane='menuOverview',button='menuResume'){if($('matchView').hidden){showView('play');}if(!menuOpen){releaseInputs();menuOwnsPause=started&&!paused&&!replay&&!(peerConnected&&peerRole==='guest'&&!serverLink?.canControl);if(menuOwnsPause)togglePause();if(replay){menuReplaySpeed=replay.getSpeed();replay.setSpeed(0);}menuOpen=true;$('pauseMenu').hidden=false;document.body.classList.add('menu-open');}refreshMenu();menuPane(pane,button);$(button).focus();}
function closeMatchMenu(resume=true){if(!menuOpen)return;menuOpen=false;$('pauseMenu').hidden=true;document.body.classList.remove('menu-open');if(resume&&menuOwnsPause&&paused)togglePause();if(resume&&replay)replay.setSpeed(menuReplaySpeed);menuOwnsPause=false;$('gameCanvas').focus();}
function toggleMatchMenu(){if(menuOpen)closeMatchMenu();else openMatchMenu();}
const originalShowView=showView;showView=function(view){if(view!=='play')closeMatchMenu(false);originalShowView(view);document.body.classList.toggle('match-active',view==='play');updateCamera();};
const originalResetMatch=resetMatch;resetMatch=function(play=true){originalResetMatch(play);if(menuOpen&&started&&!paused&&!(peerConnected&&peerRole==='guest'&&!serverLink?.canControl)){togglePause();menuOwnsPause=true;}updateCamera();};
let cameraSignature='';function updateCamera(render=true){if(!renderer)return;const rect=$('gameCanvas').getBoundingClientRect(),map=replay?.state?.stadium||stadium;if((settings.camera||'stadium')==='stadium'){renderer.followPlayerId=-1;renderer.zoomCoeff=Math.max(.1,Math.min(rect.width/(map.width*2+90),rect.height/(map.height*2+100)))*settings.zoom;}else{renderer.followPlayerId=peerRole==='guest'?networkPlayerId:1;renderer.zoomCoeff=settings.zoom;}if(render)renderer.render();}
// Refit from the active state on every frame, including remote snapshots and replay seeks.
const originalRender=renderer.render;renderer.render=function(...args){const map=replay?.state?.stadium||stadium,key=[map?.width,map?.height,settings.camera,settings.zoom,peerRole,networkPlayerId].join(':');if(key!==cameraSignature){cameraSignature=key;updateCamera(false);}return originalRender.apply(this,args);};
$('matchMenuButton').onclick=toggleMatchMenu;$('menuResume').onclick=()=>closeMatchMenu();$('menuMatch').onclick=()=>menuPane('menuMatchPane','menuMatch');$('menuVideo').onclick=()=>menuPane('menuVideoPane','menuVideo');$('menuReplays').onclick=()=>menuPane('menuReplayPane','menuReplays');$('menuChat').onclick=()=>{menuPane('menuChatPane','menuChat');$('chatInput').focus();};$('menuHelp').onclick=()=>openDialog('helpDialog');$('menuHome').onclick=()=>showView('home');$('compatButton').onclick=()=>openDialog('compatDialog');$('menuFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('matchView').requestFullscreen();}catch{notify('Fullscreen is unavailable.');}};$('fullscreenButton').onclick=$('menuFullscreen').onclick;$('menuNetwork').onclick=()=>openDialog('networkDialog');
$('cameraMode').onchange=()=>{settings.camera=$('cameraMode').value;savePrefs();updateCamera();};$('matchZoom').oninput=()=>{settings.zoom=+$('matchZoom').value;$('matchZoomValue').textContent=settings.zoom.toFixed(2)+'×';savePrefs();updateCamera();};$('matchSound').onchange=()=>{settings.sound=$('matchSound').checked;savePrefs();};
const originalLoadReplay=loadReplay;loadReplay=function(bytes,name){closeMatchMenu(false);showView('play');originalLoadReplay(bytes,name);updateCamera();};const originalCloseReplay=closeReplay;closeReplay=function(){originalCloseReplay();updateCamera();};
// Capture before gameplay input. Menu arrow keys never move a player.
window.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.code!=='Escape'&&['INPUT','TEXTAREA'].includes(e.target?.tagName))return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();if($('matchView').hidden)showView('play');else toggleMatchMenu();return;}if(menuOpen){if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.code==='ArrowDown'||e.code==='ArrowUp'){e.preventDefault();const items=menuItems.filter(id=>!$(id).hidden),index=items.findIndex(id=>$(id)===document.activeElement),next=(index+(e.code==='ArrowDown'?1:-1)+items.length)%items.length;$(items[next]).focus();}if(e.code==='Enter'){e.preventDefault();document.activeElement?.click();}e.stopImmediatePropagation();}else if(e.code==='KeyP'&&!e.repeat){e.preventDefault();e.stopImmediatePropagation();openMatchMenu();}else if(e.code==='Enter'&&$('mode').value!=='local'&&!$('matchView').hidden&&$('matchSummary').hidden){e.preventDefault();e.stopImmediatePropagation();openMatchMenu('menuChatPane','menuChat');$('chatInput').focus();}},true);
window.addEventListener('resize',updateCamera);document.addEventListener('fullscreenchange',updateCamera);
// Expose read-only report of the loaded stadium's actual physics in the menu.
showView('home');

$('pauseButton').onclick=()=>menuOpen?closeMatchMenu():openMatchMenu();
